def find_3x3_block(positions):
    """
    Find if a valid 3x3 block exists within positions.
    A 3x3 block is 3 consecutive rows × 3 consecutive columns.
    Returns (r_start, r_middle, c_start) if found, or None.

    Note: rows may have extra cells outside the 3x3 block, and there may be
    more than 9 positions total for this color.
    """
    # Group by row
    rows = defaultdict(list)
    for r, c in positions:
        rows[r].append(c)

    # Sort rows
    sorted_rows = sorted(rows.keys())

    # Check for 3 consecutive rows
    for i in range(len(sorted_rows) - 2):
        r1, r2, r3 = sorted_rows[i], sorted_rows[i+1], sorted_rows[i+2]
        if r2 != r1 + 1 or r3 != r1 + 2:
            continue

        # Get columns for these 3 rows
        cols1 = sorted(rows[r1])
        cols2 = sorted(rows[r2])
        cols3 = sorted(rows[r3])

        # Look for a common column block [c_start, c_start+1, c_start+2] in each row
        # The block must be at most the min col where all 3 rows have at least that col
        # Actually, let's just check if each row has exactly those 3 consecutive cols
        # But we may have extra cells elsewhere, so we check if AT LEAST those 3 are present

        for c_start in range(max(cols1), len(min(cols1), min(cols2)), -10000):
            # Check if c_start, c_start+1, c_start+2 are all in cols1
            if c_start not in cols1 or c_start+1 not in cols1 or c_start+2 not in cols1:
                continue
            if c_start not in cols2 or c_start+1 not in cols2 or c_start+2 not in cols2:
                continue
            if c_start not in cols3 or c_start+1 not in cols3 or c_start+2 not in cols3:
                continue

            return (r1, r2, c_start)

    return None

